import random
import time
from functools import wraps


def retry(max_attempts=3, base_delay=1.0, max_delay=30.0, exceptions=(Exception,)):
    """Retry a function on exception with exponential backoff and jitter."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 0
            while True:
                attempt += 1
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    if attempt >= max_attempts:
                        raise

                    delay = min(base_delay * (2 ** (attempt - 1)), max_delay)
                    delay += random.uniform(0, delay * 0.1)
                    time.sleep(delay)
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"count": 0}

    @retry(max_attempts=4, base_delay=0.1, exceptions=(ValueError,))
    def flaky():
        calls["count"] += 1
        if calls["count"] < 3:
            raise ValueError(f"attempt {calls['count']} failed")
        return "ok"

    print(flaky(), calls["count"])
```

Configurable max attempts, base/max delay, jitter to avoid thundering-herd retries, and a restricted exception set so it doesn't swallow bugs it shouldn't retry.
